export type RsvpPayload = {
  attending: boolean;
  name: string;
  guestCount: number;
  events: string[];
  dietary: string;
  message: string;
  submittedAt: string;
};

export type RsvpResult = {
  ok: boolean;
};

/**
 * RSVP submission boundary.
 * Replace this function with Firebase, Supabase, or a custom API later.
 */
export async function submitRsvp(payload: RsvpPayload): Promise<RsvpResult> {
  if (typeof window !== "undefined") {
    sessionStorage.setItem("wedding:rsvp", JSON.stringify(payload));
  }

  // await fetch("/api/rsvp", {
  //   method: "POST",
  //   headers: { "Content-Type": "application/json" },
  //   body: JSON.stringify(payload),
  // });

  return { ok: true };
}

export function readRsvpDraft(): RsvpPayload | null {
  if (typeof window === "undefined") return null;
  const raw = sessionStorage.getItem("wedding:rsvp");
  if (!raw) return null;
  try {
    return JSON.parse(raw) as RsvpPayload;
  } catch {
    return null;
  }
}
