"use client";

import { FormEvent, useMemo, useState } from "react";
import { ArabicText } from "@/components/decorative/Arabic";
import { Section } from "@/components/ui/Section";
import { wedding } from "@/config/wedding";
import { submitRsvp } from "@/lib/rsvp";

export function RSVP() {
  const [attending, setAttending] = useState<boolean | null>(null);
  const [name, setName] = useState("");
  const [guestCount, setGuestCount] = useState(1);
  const [selectedEvents, setSelectedEvents] = useState<string[]>([]);
  const [dietary, setDietary] = useState("");
  const [message, setMessage] = useState("");
  const [submitted, setSubmitted] = useState(false);
  const [pending, setPending] = useState(false);

  const guestOptions = useMemo(
    () => Array.from({ length: wedding.rsvp.maxGuests }, (_, i) => i + 1),
    [],
  );

  async function onSubmit(event: FormEvent) {
    event.preventDefault();
    if (attending === null) return;
    setPending(true);
    await submitRsvp({
      attending,
      name: name.trim(),
      guestCount: attending ? guestCount : 0,
      events: attending ? selectedEvents : [],
      dietary: attending ? dietary.trim() : "",
      message: message.trim(),
      submittedAt: new Date().toISOString(),
    });
    setPending(false);
    setSubmitted(true);
  }

  return (
    <Section id="rsvp">
      <p className="label section-heading">{wedding.copy.rsvpHeading}</p>
      <p className="invite-copy" style={{ marginTop: 0 }}>
        {wedding.copy.rsvpQuestion}
      </p>

      {submitted ? (
        <>
          <ArabicText className="arabic-quiet">{wedding.arabic.mashaAllah}</ArabicText>
          <p className="rsvp-thanks">{wedding.copy.rsvpThankYou}</p>
        </>
      ) : (
        <>
          <div className="rsvp-choices">
            <button
              type="button"
              className="btn is-full"
              aria-pressed={attending === true}
              onClick={() => setAttending(true)}
            >
              {wedding.copy.rsvpYes}
            </button>
            <button
              type="button"
              className="btn is-ghost is-full"
              aria-pressed={attending === false}
              onClick={() => setAttending(false)}
            >
              {wedding.copy.rsvpNo}
            </button>
          </div>

          {attending !== null && (
            <form className="rsvp-form" onSubmit={onSubmit}>
              <div className="field">
                <label htmlFor="rsvp-name">Name</label>
                <input
                  id="rsvp-name"
                  name="name"
                  autoComplete="name"
                  required
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                />
              </div>

              {attending && wedding.rsvp.showGuestCount && (
                <div className="field">
                  <label htmlFor="rsvp-guests">Number of guests</label>
                  <select
                    id="rsvp-guests"
                    value={guestCount}
                    onChange={(e) => setGuestCount(Number(e.target.value))}
                  >
                    {guestOptions.map((count) => (
                      <option key={count} value={count}>
                        {count}
                      </option>
                    ))}
                  </select>
                </div>
              )}

              {attending && wedding.rsvp.showEventSelection && (
                <div className="field">
                  <span>Events</span>
                  <div className="check-list">
                    {wedding.events.map((item) => (
                      <label key={item.id}>
                        <input
                          type="checkbox"
                          checked={selectedEvents.includes(item.id)}
                          onChange={(e) => {
                            setSelectedEvents((current) =>
                              e.target.checked
                                ? [...current, item.id]
                                : current.filter((id) => id !== item.id),
                            );
                          }}
                        />
                        {item.name}
                      </label>
                    ))}
                  </div>
                </div>
              )}

              {attending && wedding.rsvp.showDietary && (
                <div className="field">
                  <label htmlFor="rsvp-dietary">Dietary preference</label>
                  <input
                    id="rsvp-dietary"
                    value={dietary}
                    onChange={(e) => setDietary(e.target.value)}
                  />
                </div>
              )}

              {wedding.rsvp.showMessage && (
                <div className="field">
                  <label htmlFor="rsvp-message">Message</label>
                  <textarea
                    id="rsvp-message"
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                  />
                </div>
              )}

              <button className="btn is-full" type="submit" disabled={pending}>
                {pending ? "Sending" : "Send Reply"}
              </button>
            </form>
          )}
        </>
      )}
    </Section>
  );
}
